# -*- coding: utf-8 -*-
"""English translations, batch 2 (24 core OT/NT figures)."""
EN = {
"夏娃": dict(lesson="Guard the entry point of temptation",
 summary="The first woman; shaken by the serpent's sophistry, she turned to disobedience—one doubt changed everything.",
 witness="Eve's fall began with a question: did God really say that? Temptation begins not with an act but with doubting God's word. She saw the fruit was pleasing and good, and decided by her senses and logic rather than by God's word. We face the same pattern every day.",
 follow=["At first holding and rightly restating God's word","Sharing with her husband the calling to steward creation"],
 caution=["Not immediately rejecting the voice that questioned God's word","Deciding by senses and logic instead of God's command","Drawing her husband into sin with her"],
 applications=["Identify voices that question God's word and reject them at once","Before deciding, ask: am I acting on God's word or on feeling?","Don't pull others into your own wrong decisions","Renew your view of the world daily with God's word","When something looks good, take one more step and ask God's view"],
 prayer="Lord, Eve's story is my story. I too often look first, then think, and decide by feeling. Let Your word be my final authority; help me recognize the voices that question Your word and reject them the moment they begin. Amen."),
"该隐": dict(lesson="Jealousy is a killer",
 summary="The first murderer; out of jealousy that God accepted his brother Abel, he killed him—the ultimate warning of unaddressed envy.",
 witness="Cain's tragedy began with unaddressed jealousy. God had warned him: sin crouches at the door; you must master it. But he would not listen, and became a murderer. Unaddressed envy escalates to hatred, and hatred to action. God gave him a chance before the crime, and he refused it.",
 follow=["God gave him a clear warning and opportunity before things reached their worst"],
 caution=["When jealous, bottling it up instead of pouring it out to God","Ignoring God's warning and pressing on","Turning another's success into a root of hatred"],
 applications=["When jealousy arises, pray and confess to God at once","Don't read another's blessing as a denial of yourself","Accept God's individual leading for you, instead of comparing","Confide in a trusted person before negative emotions escalate","Check weekly: is there bottled-up bitterness in my heart?"],
 prayer="Lord, there are seeds of jealousy in my heart too. Help me confess to You the moment envy appears, rather than letting it take root. Let me genuinely give thanks for others' blessings, for Your leading of each person is unique. Amen."),
"亚伯": dict(lesson="Offer your best to God",
 summary="The first martyr; by faith he offered the firstborn of his flock and its fat, and was accepted by God—a brief life that became an eternal witness.",
 witness="Abel's story is short but powerful. He offered the firstborn of the flock and its fat—the best, not the convenient leftovers. His worship came from faith, and God saw his heart. Though his life was short, he entered the hall of faith in Hebrews 11 and is called one who still speaks.",
 follow=["Offering his best rather than the convenient","Worship from genuine faith and an honest heart","A short life leaving an eternal witness, influencing thousands of years"],
 caution=[],
 applications=["Don't make do in your giving—offer what truly costs","Examine your motive in worship: ritual habit, or from the heart?","Don't lower the quality of your devotion because others respond differently","Remember: even if life is short, every faithful act has eternal value","Choose one thing today and offer your best to God"],
 prayer="Lord, give me Abel's heart—not making do, not offering leftovers, but offering my best. Let my worship come from genuine faith, not religious habit or the eyes of others. Amen."),
"塞特": dict(lesson="Carrying on a godly line",
 summary="The son God gave Adam and Eve in place of the slain Abel; after Cain's killing and darkness, Seth's line began to call on the name of the LORD—a carrier of humanity's godly heritage.",
 witness="Genesis records: at that time people began to call on the name of the LORD. This brief line, in an age of killing and chaos, was the spiritual turning point left by Seth's line. Faithfully carrying on the faith, even as the world falls.",
 follow=["Still carrying on the calling on God in a dark age","Becoming a carrier of the next generation's spiritual life","Building a godly tradition in his family by his own life"],
 caution=[],
 applications=["Seth's family began to call on the LORD's name—is there spiritual heritage in your family today?","When the wider world declines, faithfully carrying on calling on God is itself a witness","Is there a next generation you can lead or influence to pass on the faith?","Begin today by calling on the name of the LORD—the most basic and vital heritage"],
 prayer="Lord, Seth's line began to call on Your name in a dark age. Help me be a carrier of faith in my family and circle, so the next generation also knows You. Amen."),
"以撒": dict(lesson="Full surrender to God",
 summary="The son of promise; on Mount Moriah he submitted to being offered as a sacrifice, foreshadowing Christ's obedience, and later became Israel's second patriarch.",
 witness="Isaac's most striking moment was on Mount Moriah: he asked his father where the offering was, and his father said God would provide. He believed. He let himself be bound on the altar without resisting. This was obedience learned from his father's faith—trusting that God would provide for him.",
 follow=["Full submission to his father's leading, foreshadowing Christ's obedience","Living quietly within the promise, a symbol of stability and peace","Trusting that God would provide, not panicking in the unknown"],
 caution=["Letting his father arrange a wife for him, with little personal seeking of God","Favoring Esau in old age, leading to family scheming and rifts"],
 applications=["Learn to submit under godly authority rather than always resisting or questioning","Build your own relationship with God directly, not only on inheritance","Treat those around you fairly, not causing conflict through favoritism","Trust that God will provide, waiting peacefully in the unknown","The lesson of Moriah: God really does provide—history has proven it"],
 prayer="Lord, Isaac's submission is the deepest lesson of faith. Help me not to struggle under Your leading, but to trust that You will provide what I need. When I don't understand Your plan, let me say: God Himself will provide. Amen."),
"雅各": dict(lesson="God changes the deceiver",
 summary="From one who deceived his brother to one renamed Israel by God—a true witness of God taking decades to change the most stubborn character.",
 witness="Jacob is one of the most real figures in Scripture—scheming, desiring, yet longing for spiritual blessing. God did not give up on him, but took decades—through marriage, work, fleeing, wrestling in the night—to change him. In one night at the Jabbok, he held on to God and would not let go, and finally received a new name.",
 follow=["A strong longing for spiritual blessing, even when his methods were wrong","At the Jabbok, refusing to let go of God until he was blessed","Finally becoming Israel, a carrier of the faith"],
 caution=["Using trickery to seize the birthright and his father's blessing","Fleeing instead of facing conflict in relationships","Favoring Joseph, causing hatred among the brothers"],
 applications=["Let longing for God exceed the desire for success","Don't fulfill God's plan by trickery—wait for God to accomplish it","Face, rather than flee, conflict in relationships","In spiritual valleys, don't give up—keep holding on to God","What conflict have you been avoiding?"],
 prayer="Lord, Jacob's story shows me Your patience with stubborn people. I too have Jacob's scheming and evasion. Thank You for not giving up on me. Let me meet You at my Jabbok—renamed, renewed, becoming the one You call me to be. Amen."),
"约瑟": dict(lesson="Forgiveness in adversity and God's sovereignty",
 summary="Sold into slavery yet raised to be governor of Egypt; he forgave his brothers, witnessing God's sovereignty in suffering.",
 witness="Joseph's life was full of injustice—envied, sold, falsely accused, forgotten. Yet he kept his character in every valley, and at last God raised him up. Most striking are his words to his brothers: you meant it for evil, but God meant it for good, to save many lives. This is the deepest declaration of God's sovereignty.",
 follow=["Keeping his character and purity amid injustice","Using his gifts to serve, whatever his circumstances","Fully forgiving those who had hurt him","Staying humble at the height of power, giving glory to God"],
 caution=["In his youth, sharing his dreams somewhat rashly, perhaps stirring his brothers' envy"],
 applications=["Keep working wholeheartedly even when misunderstood","Don't respond to unfair treatment with bitterness","Trust that God has a sovereign plan behind suffering","When you have the power to take revenge, choose forgiveness and blessing","Is there anyone you have not truly forgiven?"],
 prayer="Lord, Joseph's words are the conviction I most need: you meant it for evil, but God meant it for good. Help me trust Your sovereignty in unfair circumstances, and choose forgiveness when I have the chance for revenge. Amen."),
"约书亚": dict(lesson="Be strong and courageous to lead God's people forward",
 summary="Moses' successor; he led Israel across the Jordan, took Jericho, and conquered Canaan—a model of inheriting the promise by faith and obedience.",
 witness="God told Joshua four times: be strong and courageous. This shows he was someone who needed encouragement, not a born fearless hero. His courage came from God's word, not his temperament. At the end he said: as for me and my house, we will serve the LORD. A public declaration of personal stand.",
 follow=["Taking up Moses' burden while gripping God's promise 'be strong and courageous… I will be with you,' not shrinking from hardship (Josh 1:9)","Publicly raising the family's banner of faith: 'as for me and my house, we will serve the LORD' (Josh 24:15)","Wholeheartedly following the LORD all his life, leading Israel to keep serving God in his days (Josh 24:31)"],
 caution=[],
 applications=["How many times do you need God to tell you today, 'be strong and courageous'?","As for me and my house: do you have such a declaration?","Is there an action God is calling you to 'cross the Jordan' for?"],
 prayer="Lord, You told Joshua: be strong and courageous, do not be afraid. Say this to me today too. Help me declare openly: as for me and my house, we will serve the LORD. Amen."),
"迦勒": dict(lesson="Wholeheartedly follow God to the end",
 summary="One of the twelve spies; with Joshua he insisted on entering Canaan, and forty years later at eighty-five still asked for the hill country—a model of lifelong faithfulness.",
 witness="God said Caleb had 'a different spirit' and followed Him wholeheartedly. Forty-five years later, at eighty-five, Caleb said: give me now the hill country the LORD promised me. Still running. Age could not put out that fire.",
 follow=["When ten spies' bad report made the people lose heart, insisting 'we are well able' because he 'wholly followed the LORD' (Num 14:24)","At eighty-five, undiminished in vigor, asking for the hardest-to-take hill country of Hebron: 'give me this hill country' (Josh 14:12)","Waiting forty-five years for the promise without compromise—a model of lifelong wholehearted following"],
 caution=[],
 applications=["Does your faith still have the same passion after forty years of waiting?","God's promise is worth waiting for, even forty-five years","Go ask for that hill country today: a promise of God you have not yet claimed"],
 prayer="Lord, at eighty-five Caleb was still running, still asking for the hill country. Help my faith not to cool with age or waiting, but to follow You wholeheartedly to the end. Amen."),
"撒母耳": dict(lesson="From hearing God's voice as a child to lifelong faithful service",
 summary="The child Hannah vowed and gave back to God, raised in the temple by Eli; he heard God's call in his youth and became Israel's last judge and one of its greatest prophets.",
 witness="God called Samuel three times; thinking it was Eli, he ran to Eli three times. Eli finally understood God was speaking, and taught him to say: speak, for Your servant is listening. Then God's word came. Life's most important equipping is learning to discern God's voice—and he kept listening all his life. In 1 Sam 12:3 he declared his lifelong integrity: here I am; testify against me before the LORD.",
 follow=["Cultivating from childhood a sensitivity to hearing God's voice","Keeping integrity and faithfulness all his life, able to declare his innocence before all","Still speaking the truth when the people demanded what was against God's will"],
 caution=[],
 applications=["Can you discern God's voice? How do you tell?","Lifelong integrity is the accumulation of daily choices","Say with Samuel today: speak, for Your servant is listening"],
 prayer="Lord, from childhood Samuel learned to say: speak, for Your servant is listening. Help me come before You today in the same posture, waiting quietly for Your voice. Amen."),
"所罗门": dict(lesson="The beginning of wisdom is the fear of God",
 summary="Israel's wisest king; he built the temple and wrote Proverbs and Ecclesiastes. Early on he ruled with the fear of God as foundation, but in his later years his foreign wives turned his heart from God.",
 witness="God appeared to him twice, and he asked for wisdom to discern right from wrong, not riches. Proverbs 9:10: the fear of the LORD is the beginning of wisdom. Wisdom is not a product of the mind, but the fruit of fearing God.",
 follow=["Asking God for wisdom at the start, not success","Building the temple, putting spiritual matters first","Governing the nation with God-given insight"],
 caution=["Letting intimate relationships gradually erode his devotion to God","A divided heart, compromising between God and idols","In his later years, replacing obedience to God with human pleasure"],
 applications=["What do you long for most at the start? Ask God for wisdom, not success","Examine: are my closest relationships drawing me away from God?","The vanity of Ecclesiastes: outward achievement cannot satisfy the inner depths","Is there anything of God's that you keep postponing for other things?"],
 prayer="Lord, Solomon asked for wisdom at the start, and You gave him everything. Help me seek You first at every beginning. When I have the most, let my heart still be toward You. Amen."),
"以利亚": dict(lesson="Spiritual battle and rest",
 summary="Israel's most fiery prophet; on Mount Carmel he stood alone against 450 prophets of Baal and won; then he collapsed under the broom tree, was restored by God with bread and water, and was later taken up in a chariot of fire.",
 witness="After victory at Carmel, he entered his deepest valley: it is enough, LORD; take my life. God did not lecture—He let him sleep, and sent bread and water. The spiritual summit is often followed by the emotional valley—God knows, and tends to the body first.",
 follow=["Crying out in faith in his loneliness, and God answered","Standing in faith against 450 men","Setting out again after a deep valley"],
 caution=["In utter exhaustion, feeling isolated, that 'I alone am left'","Falling into despair right after success—lacking emotional resilience"],
 applications=["After a spiritual peak, take special care of body and emotions","Do you feel you're the only one left? God says there are still seven thousand","God gave bread and water before the mission—He tends to you before He speaks","Do you need rest first today, or prayer? Sometimes both"],
 prayer="Lord, Elijah collapsed after the peak, and You sent bread and water. Help me receive Your care first when I am exhausted, instead of forcing myself on. Thank You for not giving up on me even at my weakest. Amen."),
"以利沙": dict(lesson="A double portion of the Spirit and everyday service",
 summary="Elijah's successor; he asked for a double portion of the Spirit, performed more miracles than Elijah, and still had prophetic power at his death.",
 witness="Elisha asked not for power or fame, but for a double portion of the Spirit. His miracles—the floating axe head, the dead child raised, the leper cleansed—happened in his daily dealings with ordinary people. Miracles are not only on mountaintops, but in kitchens and fields.",
 follow=["Asking that 'the spirit that was on Elijah be doubled on me'—longing for spiritual power, not status or resources (2 Kgs 2:9)","Serving mostly ordinary little people: the poor widow's oil, the Shunammite's son, the sick servant—miracles close to daily suffering","God still with him at death—even his bones raised the dead; faithful to the very end (2 Kgs 13:21)"],
 caution=[],
 applications=["Is your longing for the Spirit stronger today than for other resources?","Miracles happen where you are willing to enter others' everyday lives"],
 prayer="Lord, Elisha asked for a double portion of the Spirit. Help me long for the Spirit above all else. Let my life too be a place where Your works happen. Amen."),
"以赛亚": dict(lesson="A vision of holiness and a call to mission",
 summary="One of the Old Testament's greatest prophets; after seeing God's glory he said 'here I am, send me'; he prophesied the Messiah's suffering and glory, writing the fullest blueprint of redemption.",
 witness="In the temple Isaiah saw God seated on a high throne, and said: woe is me, I am ruined! But God cleansed him with a burning coal, then said: who will go for us? Isaiah said: here I am, send me. After cleansing comes commissioning.",
 follow=["Honestly confessing his sin before God's holiness","Volunteering for the mission at once after being cleansed","Delivering the fullest Messianic prophecy (Isaiah 53)"],
 caution=[],
 applications=["When did you last truly sense God's holiness?","'Here I am, send me'—this is voluntary, not forced","Isaiah 53: Jesus suffered for you—what does this mean for you today?","In your sphere, who needs to hear God's message? Will you be the messenger?"],
 prayer="Lord, Isaiah was struck by Your holiness, then sent by You. Help me first know myself before Your holiness, be cleansed, and then say: here I am, send me. Amen."),
"耶利米": dict(lesson="Faithfulness in hardship",
 summary="The weeping prophet; he endured persecution, prison, and the muddy cistern, yet never stopped proclaiming God's word; his honest laments are Scripture's deepest expression of human pain.",
 witness="He said: I will not mention Him or speak any more in His name—yet there is in my heart a burning fire shut up in my bones, and I cannot hold it in. God's word was fire within him; he wanted to stop, but could not.",
 follow=["Faithfully delivering God's message under the deepest persecution","Pouring out his truest pain to God (Lamentations)","Prophesying the new covenant (Jeremiah 31)"],
 caution=[],
 applications=["Is there a fire God has placed in your heart that you keep trying to suppress?","Faithfulness does not equal results—Jeremiah preached a lifetime with almost no one turning back","Is there something God keeps telling you to say that you haven't yet spoken?","In the hardest circumstances, keep doing what God calls you to do"],
 prayer="Lord, Jeremiah had a burning fire he could not hold in. Let Your word burn in me too, so I keep speaking amid persecution and apparent fruitlessness—not for results, but for faithfulness. Amen."),
"以西结": dict(lesson="Vision that inspires hope in the dark",
 summary="A prophet in exile; in Babylon, through visions, enacted prophecies, and the image of dry bones coming to life, he conveyed God's promise of Israel's restoration.",
 witness="In the bleakest place he received the greatest vision: a valley full of dry bones—God asked: can these bones live? He answered: O Lord GOD, You know. God builds hope on the ruins of despair. That dry bones can live is the greatest declaration of faith.",
 follow=["Faithfully proclaiming God's visions in the darkness of exile, even when the people hardened their hearts (Ezek 2:5-7)","Willing to use extreme enacted prophecies (lying on his side, shaving his head, not mourning his beloved wife) to make the message pierce (Ezek 4; 24)","Seeing the vision of dry bones revived, conveying the resurrection hope: 'I will put My Spirit in you, and you shall live' (Ezek 37:14)"],
 caution=[],
 applications=["Is there a 'valley of dry bones' area in your life?","God's question: can these bones live? What is your answer?","Keep the vision God gives even in the most hopeless place"],
 prayer="Lord, in a valley of dry bones Ezekiel proclaimed a vision of resurrection. Help me believe, even in my most hopeless area, that You can make dry bones live. Amen."),
"以斯拉": dict(lesson="Revival through return to God's word",
 summary="A scribe and priest; after the return he read the Book of the Law aloud, sparking spiritual revival, and seriously dealt with the issue of Israelites marrying foreign wives.",
 witness="Ezra read the Law, and all the people wept. Then he said: this day is holy; do not grieve, for the joy of the LORD is your strength. He read God's word openly, which brought tears, and then joy. The power of the word brings both confession and celebration.",
 follow=["Reading God's word openly and seriously","Leading the people from confession to joy","Studying and practicing first, then teaching"],
 caution=[],
 applications=["How highly do you value God's word?","Read Scripture systematically and regularly, openly or privately","Reading God's word aloud can bring spiritual revival"],
 prayer="Lord, Ezra brought both tears and joy through Your word. Help me take Your word seriously, so it brings true revival in my heart. Amen."),
"尼希米": dict(lesson="Prayer and action together",
 summary="Cupbearer in the Persian court; on hearing Jerusalem's walls lay in ruins he wept and prayed, then with great organizing skill led the rebuilding of the wall—a model leader uniting faith and action.",
 witness="He prayed before the king, then immediately had a concrete plan: how much time, which materials, which checkpoints to pass. True praying faith does not exclude thorough planning. He relied on God's gracious hand, and on careful preparation.",
 follow=["Weeping and praying for God's matter, then acting","Overcoming resistance with precise plans and firm leadership","Not stopping the work despite mockery and threats"],
 caution=[],
 applications=["Have you wept over God's matters? Tears are the prelude to action","Faith and planning don't conflict—after praying, ask: what do I need to do this?","Facing enemies' mockery: we will build—an unshakable stand","Is there a burden God has put in your heart that you keep waiting for the right time to act on?"],
 prayer="Lord, Nehemiah wept for the wall, then rose to build. Help me, after weeping for Your matters, to have the same drive—turning tears into plans, and plans into building. Amen."),
"施洗约翰": dict(lesson="Preparing the way for Christ, gladly decreasing",
 summary="The prophet who prepared the Lord's way, proclaiming Christ's coming; when the crowds followed Jesus instead of him, he said: He must increase, but I must decrease.",
 witness="His disciples came saying: everyone is going to that man. He answered: the friend of the bridegroom rejoices greatly at the bridegroom's voice; this is my joy, and it is complete. I must decrease. No bitterness at being replaced—only the satisfaction of a completed mission.",
 follow=["Centering his ministry on Christ rather than himself","Gladly seeing 'his own people' turn to the true Lord","Gladly stepping back at his peak"],
 caution=[],
 applications=["In your ministry, is the center yourself or Christ?","When your 'students' surpass you, what is your reaction?","Gladly decreasing is the hardest and most important spiritual maturity"],
 prayer="Lord, John said: He must increase, but I must decrease. Help me make this the heart of my ministry and life too. Amen."),
"约翰": dict(lesson="The apostle of love who rests in the Lord",
 summary="Once a 'son of thunder' who wanted to call down fire, he matured into the apostle of love, preaching in old age just one thing: little children, love one another.",
 witness="John leaned on Jesus' chest at the Last Supper—his identity was the disciple whom the Lord loved. True maturity is not becoming more theoretical, but more loving. In old age he repeated the same line, because it was the Lord's command, and that was enough.",
 follow=["Building his relationship with Jesus on intimate dependence","In old age still holding to the command of love, not chasing more complex doctrine","Keeping watch over the witness of love amid pressure and persecution"],
 caution=[],
 applications=["John and James were sons of thunder; God changed his temperament by love—yours can be changed too","Little children, love one another—are you doing this for those around you now?","True maturity is not becoming more theoretical, but more loving","The disciple whom the Lord loved: do you sense nearness to the Lord today?"],
 prayer="Lord, John went from a son of thunder to the apostle of love. Change me too through intimacy with You—more loving as I mature, not colder as I age. Amen."),
"路得": dict(lesson="Loyalty and redemption",
 summary="A Moabite foreigner who loyally followed her mother-in-law Naomi; she became David's great-grandmother and entered the Messiah's genealogy—the highest model of loyalty.",
 witness="Ruth had a hundred reasons to leave: her husband had died, her mother-in-law told her to go back, she was a foreigner in Israel. But she said: where you go I will go. This is the most beautiful declaration of commitment. Her loyalty was not because of security, but because she chose love.",
 follow=["Choosing commitment with no guarantee whatsoever","Proving her love for God and for Naomi by action","Working humbly, not complaining about her circumstances"],
 caution=[],
 applications=["True commitment shows itself only when there is no guarantee","Faithfully serve those around you without counting the return","In a foreign or marginal situation, still choose to connect","Your loyalty will be seen by God, the Redeemer of households","What can you do today for the person near you who most needs companionship?"],
 prayer="Lord, Ruth's declaration is what I want to say to You: where You go, I will go. To choose commitment when there is no guarantee, loyalty in a strange place. Thank You for seeing every faithful act. Amen."),
"约伯": dict(lesson="Trust in suffering",
 summary="A truly righteous man who lost everything in suffering without cause, endured God's silence, and at last met God in the whirlwind—not an answer, but a truer encounter.",
 witness="Job's final victory was not an answer, but God's presence. God spoke from the whirlwind: where were you? Job said: I had heard of You by the hearing of the ear, but now my eye sees You. The suffering was never explained, yet it brought a truer encounter.",
 follow=["Still refusing to curse God in immense suffering","Honestly pouring out all his pain and questions to God","Bowing humbly before God's final response"],
 caution=[],
 applications=["Honestly questioning God in suffering is true faith, not unbelief","'I had heard of You… now my eye sees You'—suffering can deepen your knowledge of God","The best response in suffering may not be an answer, but God's presence","What is your deepest question today? Bring it honestly to God"],
 prayer="Lord, Job did not get all his answers in suffering, but he got You. Help me, in my most painful place, not to flee from You but to enter more deeply into Your presence. Amen."),
"约拿（先知）": dict(lesson="God's mercy is greater than the prophet's expectation",
 summary="A prophet who fled God's call, was swallowed by a great fish for three days, turned back to proclaim judgment, and when Nineveh repented, became angry that God forgave the city.",
 witness="He would rather die than see his enemies receive grace. This is faith's darkest corner—using God's name, but really serving his own prejudice. God asked him: is it right for you to be angry about the plant? Jonah said: it is right. God said: should I not pity Nineveh, with so many people?",
 follow=["Praying from the fish's belly and turning back in obedience"],
 caution=["Selectively unwilling for God's grace to reach certain people","Angry that God forgave his enemies","Obedience to the mission that was outward, not inward"],
 applications=["Is there a kind of person you don't want to receive God's grace?","God's mercy is greater than your preferences","Examine: is there a 'Jonah complex' hidden in your heart?"],
 prayer="Lord, Jonah's story reminds me that Your mercy is not confined to my circle. Help me open my heart to Your love for all people, including those I find hard to love. Amen."),
"撒迦利亚": dict(lesson="Victory by the Spirit, not by might",
 summary="A prophet of visions; he encouraged the returned exiles to rebuild the temple, prophesied the Messiah riding into Jerusalem on a donkey, and conveyed the message of victory by the Spirit.",
 witness="His most famous line: not by might, nor by power, but by My Spirit. This is God's word to those facing a task greater than themselves.",
 follow=["Conveying the heart of revival: 'not by might, nor by power, but by My Spirit' (Zech 4:6)","Using a series of visions to give the people hope in the low point of rebuilding: 'who has despised the day of small things?' (Zech 4:10)","Prophesying the Messiah coming 'humble and riding on a donkey,' fulfilled centuries later (Zech 9:9)"],
 caution=[],
 applications=["Before any task, first ask: is the Spirit here?","What today do you need to rely on the Spirit for, rather than your own ability?"],
 prayer="Lord, You said: not by might, nor by power, but by My Spirit. Help me rely on You like this in everything today. Amen."),
}
